# PkSize / PkSizeF 类体声明 → 对拍 rec() 标签的映射（规则三的机器闸门）
#
# 格式与口径同 oracle/rect_api.map（那份是正本），来历同 oracle/point_api.map。
#
# 这一族正是规则三的**来源案例**：Task 3 复评把 `PkSizeF::scale(qreal,qreal,mode)`
# 整个改坏（永远走 IgnoreAspectRatio），93 630 039 次比对一条都没红、
# run_oracle.sh 退出码 0 放行 —— 根因就是那个重载少写了一条 rec()。
# 当时靠人手补上并靠人手列对照表；接进解析器之后，同类漏写由机器抓：
# 头文件里多一条声明而这里没有对应行，闸门当场 FAIL。
#
# 带参构造映射到 `width;height` 的理由同 point_api.map（构造是 fixture 不是被测项）。

PkSize::PkSize()	S::defaultCtor;S::defaultPredicates
PkSize::PkSize(int,int)	S::width;S::height
PkSize::isNull()	S::isNull
PkSize::isEmpty()	S::isEmpty
PkSize::isValid()	S::isValid
PkSize::width()	S::width
PkSize::height()	S::height
PkSize::setWidth(int)	S::setWidth
PkSize::setHeight(int)	S::setHeight
PkSize::scale(int,int,Qt::AspectRatioMode)	S::scale(w,h)
PkSize::scale(const PkSize&,Qt::AspectRatioMode)	S::scale(size)
PkSize::scaled(int,int,Qt::AspectRatioMode)	S::scaled(w,h)
PkSize::scaled(const PkSize&,Qt::AspectRatioMode)	S::scaled(size)
PkSize::expandedTo(const PkSize&)	S::expandedTo
PkSize::rwidth()	S::rwidth
PkSize::rheight()	S::rheight
PkSize::operator+=(const PkSize&)	S::operator+=
PkSize::operator-=(const PkSize&)	S::operator-=
PkSize::operator*=(qreal)	S::operator*=
PkSize::operator/=(qreal)	S::operator/=
PkSize::operator==(const PkSize&,const PkSize&)	S::operator==
PkSize::operator!=(const PkSize&,const PkSize&)	S::operator!=
PkSize::operator+(const PkSize&,const PkSize&)	S::operator+
PkSize::operator-(const PkSize&,const PkSize&)	S::operator-
PkSize::operator*(const PkSize&,qreal)	S::operator*
PkSize::operator*(qreal,const PkSize&)	S::operator*(rev)
PkSize::operator/(const PkSize&,qreal)	S::operator/

PkSizeF::PkSizeF()	SF::defaultCtor;SF::defaultPredicates
PkSizeF::PkSizeF(const PkSize&)	SF::fromSize
PkSizeF::PkSizeF(qreal,qreal)	SF::width;SF::height
PkSizeF::isNull()	SF::isNull
PkSizeF::isEmpty()	SF::isEmpty
PkSizeF::isValid()	SF::isValid
PkSizeF::width()	SF::width
PkSizeF::height()	SF::height
PkSizeF::setWidth(qreal)	SF::setWidth
PkSizeF::setHeight(qreal)	SF::setHeight
PkSizeF::scale(qreal,qreal,Qt::AspectRatioMode)	SF::scale(w,h)
PkSizeF::scale(const PkSizeF&,Qt::AspectRatioMode)	SF::scale(size)
PkSizeF::scaled(qreal,qreal,Qt::AspectRatioMode)	SF::scaled(w,h)
PkSizeF::scaled(const PkSizeF&,Qt::AspectRatioMode)	SF::scaled(size)
PkSizeF::expandedTo(const PkSizeF&)	SF::expandedTo;SF::mixedExpandedTo
PkSizeF::rwidth()	SF::rwidth
PkSizeF::rheight()	SF::rheight
PkSizeF::toSize()	SF::toSize;SF::roundTrip
PkSizeF::operator+=(const PkSizeF&)	SF::operator+=
PkSizeF::operator-=(const PkSizeF&)	SF::operator-=
PkSizeF::operator*=(qreal)	SF::operator*=
PkSizeF::operator/=(qreal)	SF::operator/=
PkSizeF::operator==(const PkSizeF&,const PkSizeF&)	SF::operator==;SF::mixedEquality
PkSizeF::operator!=(const PkSizeF&,const PkSizeF&)	SF::operator!=
PkSizeF::operator+(const PkSizeF&,const PkSizeF&)	SF::operator+
PkSizeF::operator-(const PkSizeF&,const PkSizeF&)	SF::operator-
PkSizeF::operator*(const PkSizeF&,qreal)	SF::operator*
PkSizeF::operator*(qreal,const PkSizeF&)	SF::operator*(rev)
PkSizeF::operator/(const PkSizeF&,qreal)	SF::operator/
